from sympy import QQ
from sympy.polys.rings import ring
from sympy.polys.puiseux import puiseux_ring
from sympy.polys.ring_series import mul_xin, rs_pow, rs_series_inversion, rs_trunc
count = 0
for make_ring in (ring, puiseux_ring):
    R, x, y = make_ring('x,y', QQ)
    valuations = list(range(-3, 4))
    units = [R.one, 1+x, 2+3*x+x**3, 1+x*y+x**2]
    if make_ring is puiseux_ring:
        valuations += [QQ(-3, 2), QQ(1, 3), QQ(3, 2)]
        units += [1+x**QQ(1, 2)+x**QQ(2, 3)]
    for m in valuations:
        for unit in units:
            p = mul_xin(unit, 0, m)
            for n in range(-6, 0):
                for prec in range(-3, 7):
                    actual = rs_pow(p, n, x, prec)
                    expected = rs_trunc(rs_series_inversion(p**(-n), x, prec), x, prec)
                    assert actual == expected, (make_ring, p, n, prec, actual, expected)
                    count += 1
    try:
        rs_pow(R.zero, -2, x, 3)
    except ZeroDivisionError:
        pass
    else:
        raise AssertionError('Zero base must raise ZeroDivisionError')
print(f'{count} negative-power comparisons passed')
